def transform(grid):
    """Complete the periodic color bands indicated by diagonal seed bands."""
    h, w = len(grid), len(grid[0])
    # Each nonzero diagonal (down-right) has fixed difference col-row.
    marks = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                d = c - r
                if d in marks and marks[d] != v:
                    raise ValueError("non-uniform diagonal")
                marks[d] = v
    # Find the smallest period for which every observed diagonal label agrees.
    period = None
    for p in range(1, 2 * max(h, w) + 2):
        residues = {}
        okay = True
        for d, v in marks.items():
            q = d % p
            if q in residues and residues[q] != v:
                okay = False
                break
            residues[q] = v
        if okay and len(residues) == p:
            period = p
            break
    if period is None:
        # For incomplete cycles, use the smallest consistent period anyway.
        for p in range(1, 2 * max(h, w) + 2):
            residues = {}
            okay = True
            for d, v in marks.items():
                q = d % p
                if q in residues and residues[q] != v:
                    okay = False
                    break
                residues[q] = v
            if okay:
                period = p
                break
    colors = {d % period: v for d, v in marks.items()}
    # Unknown residue classes are background; seeded classes repeat across the grid.
    out = [[colors.get((c-r) % period, 0) for c in range(w)] for r in range(h)]
    return out
